pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(this)); // deployer/admin is the test contract
        vm.assume(actor != address(0));

        // anyone (even a non-admin) may become owner first via admin's setOwner
        vm.prank(address(this));
        c.setOwner(actor);

        // now a NON-admin (current owner) tries to set the owner: must revert
        vm.prank(actor);
        bool ok;
        try c.setOwner(newOwner) { ok = true; } catch { ok = false; }

        // Universal rule: only the admin may change the owner, so any call
        // from a non-admin must fail.
        assertTrue(!ok);
    }
}

